import subprocess, shutil, os, hashlib
LEAN = "def bx (φ : Nat → Prop) : Nat → Prop := fun h => ∀ g, g < h → φ g\ndef bxn : Nat → (Nat → Prop) → (Nat → Prop)\n  | 0, φ => φ\n  | n+1, φ => bx (bxn n φ)\n\ntheorem bxn_succ_iff (n : Nat) (φ : Nat → Prop) (h : Nat) :\n    bxn (n+1) φ h ↔ ∀ g, g + (n+1) ≤ h → φ g := by\n  induction n generalizing h with\n  | zero =>\n    simp only [bxn, bx]\n    exact ⟨fun H g hg => H g (by omega), fun H g hg => H g (by omega)⟩\n  | succ n ih =>\n    show bx (bxn (n+1) φ) h ↔ _\n    simp only [bx]\n    constructor\n    · intro H g hg\n      exact (ih (h-1)).1 (H (h-1) (by omega)) g (by omega)\n    · intro H g' hg'\n      exact (ih g').2 (fun g hg => H g (by omega))\n\ntheorem bxn_iff (n : Nat) (hn : 1 ≤ n) (φ : Nat → Prop) (h : Nat) :\n    bxn n φ h ↔ ∀ g, g + n ≤ h → φ g := by\n  obtain ⟨m, rfl⟩ : ∃ m, n = m + 1 := ⟨n - 1, by omega⟩\n  exact bxn_succ_iff m φ h\n\ndef gate (n : Nat) (p q : Nat → Prop) (h : Nat) : Prop :=\n  ∀ g, g < h → g < n ∨ (p g ∧ (q g ∨ ¬ ∀ j, j < g → q j))\ndef graded (k : Nat) (p : Nat → Prop) (h : Nat) : Prop :=\n  ∀ g, g + k ≤ h → p g\ndef blend (S : Nat → Prop) (a b : Nat → Prop) (h : Nat) : Prop :=\n  (S h ∧ a h) ∨ (¬ S h ∧ b h)\ndef eventual (p : Nat → Prop) : Prop := ∃ H, ∀ h, H ≤ h → p h\n\ntheorem graded_blend_unexploitable (n k : Nat) (S p q : Nat → Prop) :\n    eventual (blend S (graded k p) (gate n p q)) → eventual p := by\n  intro ⟨H, hH⟩\n  refine ⟨n + H, ?_⟩\n  intro g hg\n  rcases hH (g+k+1) (by omega) with ⟨_, hf⟩ | ⟨_, hw⟩\n  · exact hf g (by omega)\n  · rcases hw g (by omega) with hgn | ⟨hp, _⟩\n    · omega\n    · exact hp\n\ntheorem defect_blend_unexploitable (n : Nat) (S p q : Nat → Prop) :\n    eventual (blend S (fun _ => False) (gate n p q)) → eventual p := by\n  intro ⟨H, hH⟩\n  refine ⟨n + H, ?_⟩\n  intro g hg\n  rcases hH (g+1) (by omega) with ⟨_, hf⟩ | ⟨_, hw⟩\n  · exact False.elim hf\n  · rcases hw g (by omega) with hgn | ⟨hp, _⟩\n    · omega\n    · exact hp\n\ntheorem finite_cooperate_blend_unexploitable (n : Nat) (S p q : Nat → Prop)\n    (finiteS : ∃ M, ∀ h, M ≤ h → ¬ S h) :\n    eventual (blend S (fun _ => True) (gate n p q)) → eventual p := by\n  intro ⟨H, hH⟩\n  obtain ⟨M, hM⟩ := finiteS\n  refine ⟨n + H + M, ?_⟩\n  intro g hg\n  rcases hH (g+1) (by omega) with ⟨hs, _⟩ | ⟨_, hw⟩\n  · exact False.elim (hM (g+1) (by omega) hs)\n  · rcases hw g (by omega) with hgn | ⟨hp, _⟩\n    · omega\n    · exact hp\n\ntheorem cofinite_cooperate_exploited (n : Nat) (S : Nat → Prop)\n    (cofiniteS : eventual S) :\n    eventual (blend S (fun _ => True) (gate n (fun _ => False) (fun _ => False))) := by\n  obtain ⟨H, hH⟩ := cofiniteS\n  exact ⟨H, fun h hh => Or.inl ⟨hH h hh, trivial⟩⟩\n#print axioms graded_blend_unexploitable\n#print axioms defect_blend_unexploitable\n#print axioms finite_cooperate_blend_unexploitable\n#print axioms cofinite_cooperate_exploited\n"
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r = subprocess.run([binary, '--stdin'], input=LEAN, text=True, capture_output=True, timeout=100)
assert r.returncode == 0, r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms') == 4
# Negative control: removing the finite-support hypothesis must fail.
bad = LEAN.replace('(finiteS : ∃ M, ∀ h, M ≤ h → ¬ S h)', '')
r = subprocess.run([binary, '--stdin'], input=bad, text=True, capture_output=True, timeout=100)
assert r.returncode != 0
print('PASS: four general Lean blend theorems and box-power semantics; negative control rejected')
